Solution A: function initVisualizer(canvasId){const canvas=document.getElementById(canvasId);const ctx=canvas.getContext('2d');canvas.width=500;canvas.height=500;const ARRAY_SIZE=50;let array=[];let comparisons=0;let swaps=0;let isStepMode=false;let currentSpeed=500;let cancelFlag=false;let callStackDepth=0;const container=document.createElement('div');container.style.display='flex';container.style.flexDirection='column';container.style.alignItems='center';const algoSelect=document.createElement('select');['Bubble Sort','Quick Sort','Merge Sort','Heap Sort','Radix Sort'].forEach(label=>{const opt=document.createElement('option');opt.textContent=label;algoSelect.appendChild(opt);});container.appendChild(algoSelect);const speedLabel=document.createElement('label');speedLabel.textContent='Speed:';const speedSlider=document.createElement('input');speedSlider.type='range';speedSlider.min='1';speedSlider.max='1000';speedSlider.value='500';speedSlider.addEventListener('input',()=>{currentSpeed=parseInt(speedSlider.value);});container.appendChild(speedLabel);container.appendChild(speedSlider);const stepToggle=document.createElement('input');stepToggle.type='checkbox';const stepLabel=document.createElement('label');stepLabel.textContent='Step-by-step';stepLabel.style.marginLeft='5px';stepToggle.addEventListener('change',()=>{isStepMode=stepToggle.checked;});container.appendChild(stepToggle);container.appendChild(stepLabel);const nextButton=document.createElement('button');nextButton.textContent='Next';nextButton.disabled=true;container.appendChild(nextButton);const scrambleButton=document.createElement('button');scrambleButton.textContent='Scramble';scrambleButton.addEventListener('click',()=>{const patterns=['random','reverse','nearly'];const pattern=patterns[Math.floor(Math.random()*patterns.length)];scrambleArray(pattern);});container.appendChild(scrambleButton);const complexityText=document.createElement('div');complexityText.textContent='Complexity: O(n^2)';container.appendChild(complexityText);const depthText=document.createElement('div');depthText.textContent='Call Stack Depth: 0';container.appendChild(depthText);const countersText=document.createElement('div');countersText.textContent='Comparisons: 0 Swaps: 0';container.appendChild(countersText);document.body.appendChild(container);document.body.appendChild(canvas);function initArray(pattern='random'){array=[];let values=Array.from({length:ARRAY_SIZE},(_,i)=>i+1);if(pattern==='random'){for(let i=0;i<ARRAY_SIZE;i++){const j=Math.floor(Math.random()*ARRAY_SIZE);[values[i],values[j]]=[values[j],values[i]];}}else if(pattern==='reverse'){values.reverse();}else if(pattern==='nearly'){const swaps= Math.floor(ARRAY_SIZE*0.05);for(let i=0;i<swaps;i++){const a=Math.floor(Math.random()*ARRAY_SIZE);const b=Math.floor(Math.random()*ARRAY_SIZE);[values[a],values[b]]=[values[b],values[a]];}}for(let i=0;i<ARRAY_SIZE;i++){array.push({value:values[i],color:'white',index:i});}comparisons=0;swaps=0;depthText.textContent='Call Stack Depth: 0';countersText.textContent='Comparisons: 0 Swaps: 0';callStackDepth=0;}function scrambleArray(pattern){cancelCurrent();cancelFlag=false;initArray(pattern);draw();}function cancelCurrent(){cancelFlag=true;}function draw(){ctx.clearRect(0,0,500,500);const barWidth=500/ARRAY_SIZE;for(let i=0;i<ARRAY_SIZE;i++){const bar=array[i];const barHeight=bar.value*10;ctx.fillStyle=bar.color||'white';ctx.fillRect(i*barWidth,500-barHeight,barWidth-1,barHeight);}}async function waitOrStep(){if(cancelFlag)return;if(isStepMode){nextButton.disabled=false;return new Promise(resolve=>{nextButton.onclick=()=>{nextButton.disabled=true;resolve();};});}else{return new Promise(resolve=>setTimeout(resolve,currentSpeed));}}async function bubbleSort(){for(let i=0;i<ARRAY_SIZE;i++){for(let j=0;j<ARRAY_SIZE-i-1;j++){array[j].color='red';array[j+1].color='red';draw();comparisons++;await waitOrStep();if(cancelFlag)return;if(array[j].value>array[j+1].value){array[j].color='yellow';array[j+1].color='yellow';draw();swaps++;await waitOrStep();if(cancelFlag)return;[array[j],array[j+1]]=[array[j+1],array[j]];array[j].index=j;array[j+1].index=j+1;}array[j].color='white';array[j+1].color='white';}array[ARRAY_SIZE-i-1].color='green';}complexityText.textContent='Complexity: O(n^2)';draw();cancelFlag=false;}async function quickSort(start=0,end=ARRAY_SIZE-1,depth=1){if(cancelFlag)return;if(start<end){callStackDepth=depth;depthText.textContent='Call Stack Depth: '+callStackDepth;const pivotIndex=Math.floor((start+end)/2);array[pivotIndex].color='blue';draw();await waitOrStep();if(cancelFlag)return;let left=start,right=end;while(left<=right){while(array[left].value<array[pivotIndex].value){left++;}while(array[right].value>array[pivotIndex].value){right--;}if(left<=right){array[left].color='yellow';array[right].color='yellow';draw();swaps++;await waitOrStep();if(cancelFlag)return;[array[left],array[right]]=[array[right],array[left]];array[left].index=left;array[right].index=right;array[left].color='white';array[right].color='white';left++;right--;} }array[pivotIndex].color='white';await waitOrStep();if(start<right)await quickSort(start,right,depth+1);if(left<end)await quickSort(left,end,depth+1);}if(depth===1)complexityText.textContent='Complexity: O(n log n) Best/Avg, O(n^2) Worst';if(depth===1){for(let i=0;i<ARRAY_SIZE;i++)array[i].color='green';draw();}cancelFlag=false;}async function mergeSort(start=0,end=ARRAY_SIZE-1,depth=1){if(cancelFlag)return;if(start<end){callStackDepth=depth;depthText.textContent='Call Stack Depth: '+callStackDepth;const mid=Math.floor((start+end)/2);for(let i=start;i<=end;i++)array[i].color='purple';draw();await waitOrStep();if(cancelFlag)return;await mergeSort(start,mid,depth+1);await mergeSort(mid+1,end,depth+1);const left=array.slice(start,mid+1);const right=array.slice(mid+1,end+1);let i=0,j=0,k=start;while(i<left.length&&j<right.length){if(left[i].value<=right[j].value){array[k].value=left[i].value;array[k].color='yellow';k++;i++;}else{array[k].value=right[j].value;array[k].color='yellow';k++;j++;}swaps++;comparisons++;await waitOrStep();if(cancelFlag)return;}while(i<left.length){array[k].value=left[i].value;array[k].color='yellow';k++;i++;swaps++;await waitOrStep();}while(j<right.length){array[k].value=right[j].value;array[k].color='yellow';k++;j++;swaps++;await waitOrStep();}for(let i=start;i<=end;i++)array[i].color='white';draw();}if(depth===1){for(let i=0;i<ARRAY_SIZE;i++)array[i].color='green';draw();complexityText.textContent='Complexity: O(n log n) Best/Avg/Worst';}cancelFlag=false;}async function heapSort(){let heapSize=ARRAY_SIZE;async function heapify(n,size){let largest=n;const l=2*n+1;const r=2*n+2;if(l<size&&array[l].value>array[largest].value)largest=l;if(r<size&&array[r].value>array[largest].value)largest=r;if(largest!==n){array[n].color='yellow';array[largest].color='yellow';draw();swaps++;await waitOrStep();if(cancelFlag)return;[array[n],array[largest]]=[array[largest],array[n]];array[n].index=n;array[largest].index=largest;array[n].color='white';array[largest].color='white';await heapify(largest,size);} }for(let i=Math.floor(heapSize/2)-1;i>=0;i--){if(cancelFlag)return;await heapify(i,heapSize);}for(let i=heapSize-1;i>0;i--){if(cancelFlag)return;array[0].color='yellow';array[i].color='yellow';draw();swaps++;await waitOrStep();if(cancelFlag)return;[array[0],array[i]]=[array[i],array[0]];array[0].index=0;array[i].index=i;array[0].color='white';array[i].color='white';await heapify(0,i);}for(let i=0;i<ARRAY_SIZE;i++)array[i].color='green';complexityText.textContent='Complexity: O(n log n) Best/Avg/Worst';draw();cancelFlag=false;}async function radixSort(){const maxVal=Math.max(...array.map(b=>b.value));let exp=1;while(Math.floor(maxVal/exp)>0){if(cancelFlag)return;const bucket=[...Array(10)].map(()=>[]);for(let i=0;i<ARRAY_SIZE;i++){const digit=Math.floor(array[i].value/exp)%10;bucket[digit].push(array[i]);}let idx=0;for(let d=0;d<10;d++){for(const item of bucket[d]){array[idx].value=item.value;array[idx].color='yellow';swaps++;comparisons++;await waitOrStep();if(cancelFlag)return;idx++;}}exp*=10;}for(let i=0;i<ARRAY_SIZE;i++)array[i].color='green';complexityText.textContent='Complexity: O(d*(n+b)) where d digits, b=10';draw();cancelFlag=false;}async function runSort(){cancelCurrent();cancelFlag=false;for(let i=0;i<ARRAY_SIZE;i++)array[i].color='white';const algo=algoSelect.value;if(algo==='Bubble Sort')await bubbleSort();else if(algo==='Quick Sort')await quickSort();else if(algo==='Merge Sort')await mergeSort();else if(algo==='Heap Sort')await heapSort();else if(algo==='Radix Sort')await radixSort();draw();}algoSelect.addEventListener('change',runSort);scrambleButton.addEventListener('click',()=>{scrambleArray();});initArray();draw();}

